// === CONFIG CARRUSEL LA PULPE: carpetas y ajustes ===
// Los datos del negocio (teléfono, Instagram, colores) están en Recursos/datos-negocio.json.
const CONFIG = {
  carpeta_crudo_id: 'COMPLETAR_ID_CARPETA_CRUDO',
  carpeta_feed_id: 'COMPLETAR_ID_CARPETA_LISTOS_FEED',
  carpeta_edicion_id: 'COMPLETAR_ID_CARPETA_EDICION',
  datos_negocio_id: 'COMPLETAR_ID_ARCHIVO_DATOS_NEGOCIO_JSON',
  logo_id: 'COMPLETAR_ID_ARCHIVO_LOGO_PNG',
  fuente_id: 'COMPLETAR_ID_ARCHIVO_FUENTE_TTF',
  email_aviso: 'COMPLETAR@mail.com',
  espera_min: 3,      // espera a que pasen 3 min sin fotos nuevas (así ya subieron todas)
  max_fotos: 20,      // Instagram admite hasta 20 por carrusel
  max_mb: 40,         // fotos más pesadas se ignoran
};
const lote = Date.now().toString(36);
return [{ json: {
  ...CONFIG,
  lote,
  dir: `/home/node/.n8n-files/lapulpe/carrusel-${lote}`,
  fecha: new Date().toISOString().slice(0, 10),
}}];

// Agrupa las fotos de Crudo en carruseles y elige uno que ya terminó de subirse.
// Fotos llamadas "... carrusel-01.jpg", "... carrusel-02.jpg" van juntas (mismo comienzo de nombre).
// Fotos sueltas (sin "carrusel-NN") se juntan en un solo carrusel, por orden de subida.
const cfg = $('Config Carrusel').first().json;
const ahora = Date.now();
const grupos = {};
for (const it of $input.all()) {
  const f = it.json;
  if (!f.id || !String(f.mimeType || '').startsWith('image/')) continue;
  if (Number(f.size || 0) > cfg.max_mb * 1024 * 1024) continue;
  const m = String(f.name || '').match(/^(.*?)[\s_-]*carrusel[\s_-]*(\d+)/i);
  const clave = m ? m[1].trim() || 'carrusel' : '(fotos sueltas)';
  const creado = Date.parse(f.createdTime || f.modifiedTime || '') || ahora;
  (grupos[clave] = grupos[clave] || []).push({
    id: f.id, nombre: f.name, mime: f.mimeType, creado,
    orden: m ? Number(m[2]) : creado,
    descripcion: String(f.description || '').trim(),
  });
}
const listos = Object.entries(grupos)
  .map(([clave, fotos]) => ({ clave, fotos, ultimo: Math.max(...fotos.map(x => x.creado)), primero: Math.min(...fotos.map(x => x.creado)) }))
  .filter(g => ahora - g.ultimo >= cfg.espera_min * 60 * 1000)   // nadie subió nada en los últimos minutos
  .sort((a, b) => a.primero - b.primero);
if (!listos.length) return [];                                      // nada listo: el flujo termina acá sin error
const g = listos[0];
const fotos = g.fotos.sort((a, b) => a.orden - b.orden || a.creado - b.creado).slice(0, cfg.max_fotos);
const descripcion = fotos.map(x => x.descripcion).find(Boolean) || '';
return [{ json: { grupo: g.clave, total: fotos.length, descripcion, fotos } }];

// === Datos del negocio: se leen de datos-negocio.json (Drive) en cada video ===
// Para cambiar teléfono, Instagram, hashtags, etc., se edita ese archivo, no n8n.
const salida = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  let d;
  try { d = JSON.parse(buf.toString('utf8').replace(/^﻿/, '')); }
  catch (e) { throw new Error('datos-negocio.json tiene un error de formato (revisá comas y comillas): ' + e.message); }
  if (!d.nombre) throw new Error('Falta "nombre" en datos-negocio.json');
  d.hashtags_base = Array.isArray(d.hashtags_base) ? d.hashtags_base : [];
  // Pie fijo del caption: lo agregamos nosotros, no Claude, para que el teléfono nunca salga mal
  d.pie_caption = [
    d.telefono_reservas ? `📞 Reservas: ${d.telefono_reservas}` : '',
    d.direccion ? `📍 ${d.direccion}` : '',
    d.horario ? `🕛 ${d.horario}` : '',
  ].filter(Boolean).join('\n');
  const hex = (c, def) => (/^#?[0-9a-fA-F]{6}$/.test(String(c || '')) ? String(c).replace('#', '') : def);
  d.ff_marco = '0x' + hex(d.color_marco, 'F3EBDD');   // formato de color para FFmpeg
  d.ff_texto = '0x' + hex(d.color_texto, '1A1A1A');
  salida.push({ json: d, pairedItem: { item: i } });
}
return salida;

// Una fila por foto, con los textos de la banda de abajo de cada placa
const cfg = $('Config Carrusel').first().json;
const d = $('Datos del negocio').first().json;
const sel = $('Elegir carrusel').first().json;
const b64 = t => Buffer.from(String(t || ''), 'utf8').toString('base64');
return sel.fotos.map((f, i) => {
  const n = i + 1, nn = String(n).padStart(2, '0');
  const ultima = n === sel.total && sel.total > 1;
  const ext = f.mime === 'image/png' ? 'png' : (f.mime === 'image/webp' ? 'webp' : 'jpg');
  return { json: {
    file_id: f.id, nombre_original: f.nombre, n, total: sel.total,
    ruta: `${cfg.dir}/foto-${nn}.${ext}`,
    placa: `${cfg.dir}/placa-${nn}.jpg`,
    mini: `${cfg.dir}/mini-${nn}.jpg`,
    // última placa: reservas; las demás: Instagram
    linea1_b64: b64(ultima ? (d.historia_linea_1 || ('RESERVAS ' + (d.telefono_reservas || ''))) : (d.instagram || d.nombre)),
    linea2_b64: b64(d.horario || ''),
    contador_b64: b64(`${n}/${sel.total}`),
    l1_size: ultima ? 34 : 30,
  }};
});

