={{ (() => {
  // PLACA 4:5 (1080x1350): la foto entera (con fondo desenfocado de la misma foto), marco crema,
  // banda de abajo con logo, Instagram/horario (o RESERVAS en la última) y el número de placa.
  const c = $('Config Carrusel').first().json;
  const d = $('Datos del negocio').first().json;
  const f = $('Una foto por item').item.json;
  const nn = String(f.n).padStart(2, '0');
  const W = 1000, H = 1170;
  const fill = `split[a][b];[a]scale=${W}:${H}:force_original_aspect_ratio=increase,crop=${W}:${H},boxblur=24:2,eq=brightness=-0.06[bg];[b]scale=${W}:${H}:force_original_aspect_ratio=decrease[fg];[bg][fg]overlay=(W-w)/2:(H-h)/2,setsar=1`;
  const font = `fontfile=${c.dir}/fuente.ttf:expansion=none:fontcolor=${d.ff_texto}`;
  const txt = (nombre, b64) => `printf '%s' '${b64}' | base64 -d > "${c.dir}/${nombre}.txt" && `;
  const fc = `[0:v]${fill}[foto];[2:v][foto]overlay=40:40[a];[1:v]scale=-1:100,colorkey=0xFFFFFF:0.12:0.08[lg];[a][lg]overlay=40:1228[b];` +
    `[b]drawtext=${font}:textfile=${c.dir}/l1-${nn}.txt:fontsize=${f.l1_size}:x=170:y=1240,` +
    `drawtext=${font}:textfile=${c.dir}/l2-${nn}.txt:fontsize=24:x=170:y=1288,` +
    `drawtext=${font}:textfile=${c.dir}/n-${nn}.txt:fontsize=30:x=w-text_w-44:y=1262[out]`;
  return txt(`l1-${nn}`, f.linea1_b64) + txt(`l2-${nn}`, f.linea2_b64) + txt(`n-${nn}`, f.contador_b64) +
    `ffmpeg -hide_banner -loglevel error -y -i "${f.ruta}" -i "${c.dir}/logo.png" -f lavfi -i color=c=${d.ff_marco}:s=1080x1350:d=1` +
    ` -filter_complex "${fc}" -map "[out]" -frames:v 1 -q:v 2 "${f.placa}"` +
    ` && ffmpeg -hide_banner -loglevel error -y -i "${f.ruta}" -vf "scale='min(768,iw)':-2" -frames:v 1 -q:v 5 "${f.mini}"`;
})() }}

