// Arma UN pedido a Claude con todas las fotos (miniaturas) para escribir título y caption.
const d = $('Datos del negocio').first().json;
const sel = $('Elegir carrusel').first().json;
const items = $input.all();
const contenido = [];
for (let i = 0; i < items.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  contenido.push({ type: 'text', text: `Foto ${i + 1} de ${items.length}:` });
  contenido.push({ type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: buf.toString('base64') } });
}
contenido.push({ type: 'text', text:
  'Estas fotos van juntas en un carrusel de Instagram, en este orden.' +
  (sel.descripcion ? `\nNota de quien las subió: "${sel.descripcion}"` : '') +
  '\nEscribí el título, el texto de portada, el caption y los hashtags.' });
const pedido = {
  model: 'claude-opus-5-5',
  max_tokens: 4000,
  fallbacks: 'default',
  output_config: {
    effort: 'low',
    format: { type: 'json_schema', schema: {
      type: 'object',
      properties: {
        titulo: { type: 'string' },
        gancho: { type: 'string' },
        caption: { type: 'string' },
        hashtags: { type: 'array', items: { type: 'string' } },
      },
      required: ['titulo', 'gancho', 'caption', 'hashtags'],
      additionalProperties: false,
    }},
  },
  system: `Sos el community manager de ${d.nombre} (${d.descripcion}; rubro: ${d.rubro}; abre: ${d.horario}). Tono: ${d.tono}.\n` +
    'Mirás las fotos de un carrusel de Instagram (pueden traer textos escritos encima: usalos) y escribís:\n' +
    '- titulo: corto (máx. 8 palabras), para nombrar la carpeta.\n' +
    '- gancho: texto para la portada del carrusel, máx. 6 palabras, que invite a deslizar.\n' +
    '- caption: 2 a 4 oraciones para Instagram, con un llamado a la acción al final. Podés usar 1 o 2 emojis.\n' +
    '- hashtags: 3 a 6 hashtags relevantes en español, con #.\n' +
    'No escribas teléfono, dirección ni horario en el caption: se agregan solos al final. ' +
    'REGLAS: no inventes precios, platos, promociones ni datos que no se vean en las fotos o en la nota.',
  messages: [{ role: 'user', content: contenido }],
};
return [{ json: { pedido } }];

const r = $input.first().json;
if (r.stop_reason === 'refusal') throw new Error('Claude no quiso escribir este caption: revisá las fotos a mano');
const bloque = (r.content || []).find(b => b.type === 'text');
if (!bloque) throw new Error('Claude no devolvió texto');
const t = JSON.parse(bloque.text);
const cfg = $('Config Carrusel').first().json;
const datos = $('Datos del negocio').first().json;
const hashtags = [...new Set([...(datos.hashtags_base || []), ...(t.hashtags || [])])].join(' ');
const limpio = String(t.titulo || 'carrusel').replace(/[\\/:*?"<>|]/g, '').slice(0, 60).trim();
const palabras = String(t.gancho || t.titulo || datos.nombre).toUpperCase().split(/\s+/).filter(Boolean);
const renglones = [];
for (const p of palabras) {
  const ult = renglones[renglones.length - 1];
  if (ult !== undefined && (ult + ' ' + p).length <= 18) renglones[renglones.length - 1] = ult + ' ' + p;
  else renglones.push(p);
}
const b64 = s => Buffer.from(String(s || ''), 'utf8').toString('base64');
return [{ json: {
  titulo: t.titulo,
  gancho: t.gancho,
  caption: [String(t.caption || '').trim(), datos.pie_caption].filter(Boolean).join('\n\n'),
  hashtags,
  nombre_carpeta: `${cfg.fecha} - Carrusel - ${limpio}`,
  tapa_b64: b64(renglones.slice(0, 3).join('\n')),
  tapa_pie_b64: b64([datos.instagram, datos.telefono_reservas ? 'Reservas ' + datos.telefono_reservas : ''].filter(Boolean).join('  ·  ')),
}}];

